          </video>
          {videoPlaybackError && (
            <p className="memory-video__error" role="status">
              Video belum bisa diputar otomatis. Tekan tombol putar untuk memulai.
            </p>
          )}
        </section>

        <section className="birthday-wishes section birthday-slide" id="wishes" aria-labelledby="birthday-wishes-title">
          <p className="eyebrow">DOA KECIL DARIKU</p>
          <h2 id="birthday-wishes-title">Harapan untukmu</h2>
          <p className="section-desc">Pilih satu harapan, ya ♡</p>
          <div className="birthday-wishes__choices">
            {BIRTHDAY_WISHES.map((wish, index) => (
              <button
                aria-pressed={selectedWish === index}
                className={`birthday-wishes__choice${selectedWish === index ? " is-selected" : ""}`}
                key={wish.label}
                onClick={() => setSelectedWish(index)}
                type="button"
              >
                <span aria-hidden="true">{wish.emoji}</span>
                {wish.label}
              </button>
            ))}
          </div>
          <p className="birthday-wishes__message" aria-live="polite">
            {BIRTHDAY_WISHES[selectedWish].message}
          </p>
        </section>

        <section className="birthday-song section birthday-slide" id="birthday-song" aria-label="Lagu hadiah tak seberapa">
          <p className="eyebrow">A LITTLE SONG FOR YOU</p>
          <div className="birthday-song__notes" aria-hidden="true">♫ ♪ ♫</div>
          <h2>Hadiah Tak Seberapa</h2>
          <p className="section-desc">Untuk kamu yang super membanggakan ♡</p>
          <div className="birthday-song__verses">
            {birthdaySongVerses.map((verse, index) => (
              <article
                className="birthday-song__verse is-visible"
                key={index}
                style={{ "--verse-delay": `${index * 0.55}s` }}
              >
                {verse.map((line) => <p key={line}>{line}</p>)}
              </article>
            ))}
          </div>
        </section>

      </div>
    </main>
      )}
    </>
  );
}
